                        if 0 <= new_i < shifted.shape[0] and 0 <= new_j < shifted.shape[1]:
                            shifted[new_i, new_j] = input_grid[i, j]

                if np.array_equal(shifted, output_grid):
                    return True

        return True  # Default to movement if colors preserved and positions changed
    except:
        return False

